PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?youngerFilm ?youngerFilmLabel ?youngerDirector ?youngerDirectorLabel ?youngerBirth WHERE {
  VALUES (?f1 ?f2) { (dbr:Vadakakku_Oru_Hridayam <http://dbpedia.org/resource/The_$1,000,000_Reward>) }
  ?f1 dbo:director ?d1 .
  ?f2 dbo:director ?d2 .
  ?d1 dbo:birthDate ?b1 .
  ?d2 dbo:birthDate ?b2 .
  {
    FILTER (?b1 > ?b2)
    BIND(?f1 AS ?youngerFilm)
    BIND(?d1 AS ?youngerDirector)
    BIND(?b1 AS ?youngerBirth)
  }
  UNION
  {
    FILTER (?b2 > ?b1)
    BIND(?f2 AS ?youngerFilm)
    BIND(?d2 AS ?youngerDirector)
    BIND(?b2 AS ?youngerBirth)
  }
  OPTIONAL { ?youngerFilm rdfs:label ?youngerFilmLabel . FILTER(lang(?youngerFilmLabel) = "en") }
  OPTIONAL { ?youngerDirector rdfs:label ?youngerDirectorLabel . FILTER(lang(?youngerDirectorLabel) = "en") }
}

